<template><span v-if="!air" class="mc-item" :class="{'with-name':showName}"><button class="mc-item-button" :style="{width:size+'px',height:size+'px'}" :title="displayName+' · '+id" @click="openItem(id,stack)" :aria-label="displayName"><ModelPreview v-if="item" :url="preview" :size="size" :label="displayName"/><span v-else class="item-loading">·</span><span v-if="count>1" class="mc-count">{{count}}</span></button><span v-if="showName" class="mc-item-label">{{displayName}}</span></span></template>
<script setup lang="ts">
import {sameValue} from '../../../shared/value.mjs';
import{ref,computed,onMounted}from'vue';import{useData}from'vitepress';import{getData,nameOf,fullId,openItem}from'../lib/wiki';import ModelPreview from'./ModelPreview.vue';
const props=withDefaults(defineProps<{id:string;count?:number;size?:number;name?:string;showName?:boolean;showTooltip?:boolean;stack?:any}>(),{count:1,size:32,showName:false,showTooltip:true});const{lang}=useData();const catalog=ref<any>();const id=computed(()=>fullId(props.id)),air=computed(()=>!props.id||id.value==='minecraft:air'),item=computed(()=>catalog.value?.items[id.value]);const chosen=computed(()=>{const patch=props.stack?.components;return patch&&item.value?.variants.find((v:any)=>Object.entries(patch).every(([k,n])=>sameValue(({...item.value.components,...v.components})[k],n)))});const displayName=computed(()=>nameOf(chosen.value??item.value,lang.value)||props.name||id.value);const preview=computed(()=>chosen.value?.model??item.value?.model);onMounted(async()=>{catalog.value=await getData()});
</script>
